create or replace function finance_private.current_period_create_worker_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.current_actor_can_create_finance_period(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid) returns boolean language sql stable security definer set search_path='' as $$select false$$;
revoke all on function finance_private.current_period_create_worker_is_trusted() from public,anon,authenticated;
