create or replace function finance_api.authorize_finance_period_create(p_dealer_account_id uuid,p_branch_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$
 select case when p_permission='finance.periods.create' and auth.uid() is not null and finance_private.current_actor_can_create_finance_period(auth.uid(),da.legal_entity_id,da.id,b.id) then pg_catalog.jsonb_build_object('allowed',true,'legalEntityId',da.legal_entity_id) else pg_catalog.jsonb_build_object('allowed',false) end from finance.dealer_accounts da join finance.branches b on b.id=p_branch_id and b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.status in('SHADOW','ACTIVE') and b.status='ACTIVE'
$$;
create or replace function finance_api.commit_finance_period_create(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_period_start date,p_period_end date,p_currency_code text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare h finance.finance_periods%rowtype;c finance.finance_periods%rowtype;e jsonb;v_hash text;v_payload jsonb;v_payload_hash text;v_previous text;v_audit text;v_created boolean:=false;
begin
 if not finance_private.current_period_create_worker_is_trusted() then raise exception using errcode='42501',message='period create worker denied';end if;
 if p_actor_id is null or p_legal_entity_id is null or p_dealer_account_id is null or p_branch_id is null or p_period_start is null or p_period_end is null or p_period_start>p_period_end or p_currency_code!~'^[A-Z]{3}$' or coalesce(pg_catalog.btrim(p_idempotency_key),'')='' or pg_catalog.length(p_idempotency_key)>200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required period create fields missing';end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.id=p_branch_id and b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.currency_code=p_currency_code and da.status in('SHADOW','ACTIVE') and b.status='ACTIVE') then raise exception using errcode='42501',message='branch period scope mismatch';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('period-create:'||p_legal_entity_id||':'||p_period_start||':'||p_period_end||':'||p_currency_code||':'||p_dealer_account_id||':'||p_branch_id,0));
 select om.payload,om.payload->>'intentHash' into e,v_hash from finance.outbox_messages om where om.aggregate_type='finance_period' and om.event_type='FINANCE_PERIOD_CREATED' and om.payload->>'idempotencyKey'=p_idempotency_key and om.legal_entity_id=p_legal_entity_id order by om.created_at_utc desc,om.id desc limit 1;
 if found then if v_hash=p_intent_hash then return e||pg_catalog.jsonb_build_object('outcome','REPLAY');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if exists(select 1 from finance.finance_periods fp where fp.legal_entity_id=p_legal_entity_id and fp.scope_type='HEADQUARTERS' and fp.currency_code=p_currency_code and fp.mode='LIVE' and not(fp.period_end<p_period_start or fp.period_start>p_period_end) and (fp.period_start<>p_period_start or fp.period_end<>p_period_end)) then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 insert into finance.finance_periods(legal_entity_id,scope_type,period_start,period_end,currency_code,mode,status,version,created_by,correlation_id) values(p_legal_entity_id,'HEADQUARTERS',p_period_start,p_period_end,p_currency_code,'LIVE','OPEN',1,p_actor_id,p_correlation_id) on conflict do nothing;
 select * into h from finance.finance_periods fp where fp.legal_entity_id=p_legal_entity_id and fp.scope_type='HEADQUARTERS' and fp.period_start=p_period_start and fp.period_end=p_period_end and fp.currency_code=p_currency_code and fp.mode='LIVE' for update;
 if not found then raise exception using errcode='23514',message='headquarters finance period unavailable';end if;
 insert into finance.finance_periods(legal_entity_id,parent_period_id,scope_type,dealer_account_id,branch_id,period_start,period_end,currency_code,mode,status,version,created_by,correlation_id) values(p_legal_entity_id,h.id,'BRANCH',p_dealer_account_id,p_branch_id,p_period_start,p_period_end,p_currency_code,'LIVE','OPEN',1,p_actor_id,p_correlation_id) on conflict do nothing returning * into c;
 if found then v_created:=true;else select * into c from finance.finance_periods fp where fp.parent_period_id=h.id and fp.scope_type='BRANCH' and fp.dealer_account_id=p_dealer_account_id and fp.branch_id=p_branch_id for update;end if;
 if c.period_start<>p_period_start or c.period_end<>p_period_end or c.currency_code<>p_currency_code or c.legal_entity_id<>p_legal_entity_id then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not v_created then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 v_payload:=pg_catalog.jsonb_build_object('periodId',c.id,'parentPeriodId',h.id,'dealerAccountId',c.dealer_account_id,'branchId',c.branch_id,'periodStart',c.period_start,'periodEnd',c.period_end,'currencyCode',c.currency_code,'status',c.status,'sourceSnapshotHash',c.source_snapshot_hash,'checkSnapshotHash',c.check_snapshot_hash,'lockedAtUtc',c.locked_at_utc,'version',c.version,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.period','FINANCE_PERIOD_CREATED','finance_period',c.id,c.version,v_payload,v_payload_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id,0));select ae.integrity_hash into v_previous from finance.audit_events ae where ae.legal_entity_id=p_legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||c.id||':FINANCE_PERIOD_CREATED:'||v_payload_hash||':'||p_correlation_id,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','FINANCE_PERIOD_CREATED','finance_period',c.id,'ALLOW',v_payload_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('parentPeriodId',h.id,'branchId',p_branch_id),p_correlation_id);
 return v_payload||pg_catalog.jsonb_build_object('outcome',case when v_created then 'CREATED' else 'REPLAY' end);
end$$;
revoke all on function finance_api.authorize_finance_period_create(uuid,uuid,text) from public,anon;
revoke all on function finance_api.commit_finance_period_create(uuid,uuid,uuid,uuid,date,date,text,text,text,uuid) from public,anon,authenticated;
